 "content": "def transform(grid):
    """Return one background/marker indicator per cell in a separator-defined grid."""
    h, w = len(grid), len(grid[0])
    solid_rows = [(r, grid[r][0]) for r in range(h) if all(v == grid[r][0] for v in grid[r])]
    solid_cols = [(c, grid[0][c]) for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    # Full-width uniform lines are the horizontal separators; their color also
    # identifies the vertical separators.
    sep = solid_rows[0][1]
    row_seps = [r for r, color in solid_rows if color == sep]
    col_seps = [c for c, color in solid_cols if color == sep]
    colors = {v for row in grid for v in row}
    background = next(v for v in colors if v != sep and sum(row.count(v) for row in grid) > 1)
    marker = next(v for v in colors if v != sep and v != background)

    def spans(length, cuts):
        result, start = [], 0
        for cut in cuts:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < length:
            result.append((start, length))
        return result

    rg, cg = spans(h, row_seps), spans(w, col_seps)
    out = [[background for _ in cg] for _ in rg]
    for i, (r0, r1) in enumerate(rg):
        for j, (c0, c1) in enumerate(cg):
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if grid[r][c] == marker and (
                        (r + 1 < r1 and grid[r + 1][c] == marker) or
                        (c + 1 < c1 and grid[r][c + 1] == marker)
                    ):
                        out[i][j] = 1
                        break
                if out[i][j] == 1:
                    break
    return out
