 "content": "def transform(grid):
    """Extract marker counts from cells in a separator grid."""
    h, w = len(grid), len(grid[0])
    # separators are full solid rows/columns; determine them by uniformity
    solid_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    solid_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    sep_color = grid[solid_rows[0]][0]
    def spans(n, cuts):
        result, last = [], 0
        for x in cuts:
            if last < x: result.append((last, x))
            last = x + 1
        if last < n: result.append((last, n))
        return result
    rs = spans(h, solid_rows)
    cs = spans(w, solid_cols)
    vals = {x for row in grid for x in row}
    bg = max((x for x in vals if x != sep_color), key=lambda x: sum(row.count(x) for row in grid))
    marker = next(x for x in vals if x not in (sep_color, bg))
    out = [[bg for _ in cs] for _ in rs]
    for i, (r0, r1) in enumerate(rs):
        for j, (c0, c1) in enumerate(cs):
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if grid[r][c] == marker and ((r+1<r1 and grid[r+1][c]==marker) or (c+1<c1 and grid[r][c+1]==marker)):
                        out[i][j] = 1
